theorem Script.trans {x y z : Word} {d₁ i₁ d₂ i₂ : ℕ}
    (hxy : Script x y d₁ i₁) (hyz : Script y z d₂ i₂) :
    Script x z (d₁ + d₂) (i₁ + i₂)

theorem alignment_of_common_subsequence {w y z : Word}
    (hy : w.Sublist y) (hz : w.Sublist z) :
    Alignment y z (y.length - w.length) (z.length - w.length)

theorem editedFamily_negative {B : Type*} {k : ℕ}
    (bubbles : B → BubbleWord k) (rank : B → ℕ) (b : B) :
    (editedFamily bubbles rank).family.path b false = listLetters (bubbles b).negativeWord

theorem editedFamily_positive {B : Type*} {k : ℕ}
    (bubbles : B → BubbleWord k) (rank : B → ℕ) (b : B) :
    (editedFamily bubbles rank).family.path b true = listLetters (bubbles b).positiveWord

theorem rule_support_eq_edge_union {B : Type*} (F : Family B) (L : ℕ)
    (H : BubbleGeometry F L) (S : Finset B) (hdis : VertexDisjointOn F L S) :
    {g | ruleSpectrum F L S g ≠ 0} = {g | ∃ b ∈ S, HasGram F L b g}

theorem generatingData_finite (x : Letters) (n k ν c : ℕ)
    (hν : 1 ≤ ν) (hx : KUnique x n k) :
    Finite {data : RecoveredData ν // GeneratingData x n k ν c data}

theorem generatingRuleSet_finite (x : Letters) (n k ν R c : ℕ) (group : Fin ν → Fin R)
    (hν : 1 ≤ ν) (hx : KUnique x n k) :
    Finite {Q : RuleSet k // GeneratingRuleSet x n k ν R c group Q}

theorem ValidCatalogue.geometry {k ν R : ℕ}
    {bubbles : Fin ν → BubbleWord k} {group : Fin ν → Fin R}
    (h : ValidCatalogue bubbles group) :
    BubbleGeometry (indexedFamily bubbles group).family (windowLength k)

theorem ValidCatalogue.rank_disjoint {k ν R : ℕ}
    {bubbles : Fin ν → BubbleWord k} {group : Fin ν → Fin R}
    (h : ValidCatalogue bubbles group) :
    ∀ i, VertexDisjointOn (indexedFamily bubbles group).family (windowLength k)
      (ruleBubbles (indexedFamily bubbles group).family i)

theorem catalogue_singleton_component_count_le {t k : ℕ}
    (w : Gram (windowLength k) → ℤ) (hw : CatalogueRule t k w) :
    componentCount {w} ≤ 2 * t

theorem singleton_fiber_count_bound {A C : Type*} [Fintype A] [Fintype C]
    (f : A → C) (hsurj : Function.Surjective f) :
    2 * Fintype.card C ≤ Fintype.card A + Fintype.card {c : C // SingletonFiber f c}

theorem connected_mono {L : ℕ} {Q S : Finset (Gram L → ℤ)}
    (hsub : CoordinateSupportIncluded Q S) {u v : Vertex L}
    (hc : RuleSetConnected Q u v) : RuleSetConnected S u v

theorem edge_mono {L : ℕ} {Q S : Finset (Gram L → ℤ)}
    (hsub : CoordinateSupportIncluded Q S) {u v : Vertex L}
    (he : RuleSetEdge Q u v) : RuleSetEdge S u v

theorem incident_mono {L : ℕ} {Q S : Finset (Gram L → ℤ)}
    (hsub : CoordinateSupportIncluded Q S) {v : Vertex L}
    (hv : Incident Q v) : Incident S v

theorem catalogue_vertex_card_le {t k : ℕ}
    (w : Gram (windowLength k) → ℤ) (hw : CatalogueRule t k w) :
    Fintype.card (RuleSetVertex {w}) ≤ 4 * t * windowLength k

theorem GeneratingAt.restrict {k : ℕ} {v : Gram (windowLength k) → ℤ}
    {G U : RuleSet k} (hgen : GeneratingAt v G) (hUG : U ⊆ G)
    (hclosed : ClosedIn G U) : GeneratingAt v U

theorem generating_blockHull {k : ℕ} {v : Gram (windowLength k) → ℤ}
    {G : RuleSet k} (hgen : GeneratingAt v G) (I : RuleSet k) :
    GeneratingAt v (RelationBlockSavings.blockHull G I)

theorem generating_blockOf {k : ℕ} {v : Gram (windowLength k) → ℤ}
    {G : RuleSet k} (hgen : GeneratingAt v G) (a : Gram (windowLength k) → ℤ) :
    GeneratingAt v (blockOf G a)

theorem sum_displacements {V : Type*} [AddCommGroup V] {m : ℕ}
    (p : Fin (m + 1) → V) :
    (∑ i : Fin m, (p i.succ - p i.castSucc)) = p (Fin.last m) - p 0

theorem ScanState.earlier_span {step : Fin m → V} {Good : Finset (Fin m) → Prop}
    {n : ℕ} {S : Finset (Fin m)} (h : ScanState step Good n S)
    (j : Fin m) (hj : j.val < n) : step j ∈ selectedSpan step S

theorem ScanState.generating {H : Type*} {p : Fin (m + 1) → H → ℚ}
    {Good : Finset (Fin m) → Prop} {n : ℕ} {S : Finset (Fin m)}
    (hs : ScanState (walkStep p) Good n S)
    (hp : ∀ j, WitnessAlgebra.BooleanVector (p j)) : GeneratingSelected p S

theorem ScanState.generating_after_append {H : Type*} {p : Fin (m + 1) → H → ℚ}
    {Good : Finset (Fin m) → Prop} {n : ℕ} {S : Finset (Fin m)}
    (hs : ScanState (walkStep p) Good n S)
    (hp : ∀ j, WitnessAlgebra.BooleanVector (p j))
    (i : Fin m) (hi : i.val = n) (hout : walkStep p i ∉ selectedSpan (walkStep p) S) :
    GeneratingSelected p (insert i S)

theorem generatingSet_finite (x : Letters) (n k ν R c : ℕ) (group : Fin ν → Fin R)
    (hν : 1 ≤ ν) (hx : KUnique x n k) :
    Finite {Q : RuleSet k // GeneratingSet x n k ν R c group Q}

theorem generatingSet_finite (t : ℕ) (ht : 1 ≤ t) (x : Letters)
    (n k R c : ℕ) (hR : 1 ≤ R) (hx : KUnique x n k) :
    Finite {Q : RuleSet k // GeneratingSet t x n k R c Q}

theorem avoids_later_of_not_avoids {k start next edit : ℕ}
    (hgap : start + k ≤ next) (hbad : ¬ Avoids k start edit) :
    Avoids k next edit

theorem source_intervals_disjoint {k a b : ℕ} {source target₁ target₂ : List Bool}
    {orientation₁ orientation₂ : Orientation}
    (p : RunBubbleConstruction.LocalBubble k source target₁ a orientation₁)
    (q : RunBubbleConstruction.LocalBubble k source target₂ b orientation₂)
    (hgap : a + 4 * windowLength k ≤ b) :
    Disjoint (LocalBubble.sourceInterval p) (LocalBubble.sourceInterval q)

theorem edge_catalogue {t k n Q : ℕ} {H : Spectrum k →+ UnitAddCircle}
    {x y : Vertex (n := n) t Q H} (hxy : (graph t Q H).Adj x y) :
    ConnectedBlocks.CatalogueRule t k (spectrum k y.val - spectrum k x.val)

theorem edge_surviving {t k n Q : ℕ} {H : Spectrum k →+ UnitAddCircle}
    (hQ : 2 ≤ Q) {x y : Vertex (n := n) t Q H} (hxy : (graph t Q H).Adj x y) :
    spectrum k y.val - spectrum k x.val ∈ surviving t Q H

theorem allowed_of_bounds {t k R : ℕ} {U : RuleSet k}
    (hcard : U.card = R) (hb : WitnessBounds t k U) :
    AllowedComponents t k R (componentCount U)

theorem candidate_finite (t : ℕ) (ht : 1 ≤ t) (x : Letters)
    (n k R : ℕ) (hR : 1 ≤ R) (hx : KUnique x n k) :
    Finite {U : RuleSet k // Candidate t x n k R U}
